program.compute:
options = read('/input/options')
result = []
for size in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(options, size):
        ids = [item['id'] for item in group]
        if valid(ids):
            result = ids
            break
    if result:
        break

program.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
    if valid(selection):
        if status('report') == 'not_sent':
            send('report', 'team', selection)
        elif status('report') == 'sent':
            pass
        else:
            pass
else:
    write('/output/selection', result)
    send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')

